const items = $input.all();

// Normalización de texto: elimina tildes,
// uniformiza mayúsculas y espacios.
const normalize = (value) =>
  String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, " ")
    .trim();

const hasAny = (text, terms) =>
  terms.some((term) => text.includes(term));

const findMatches = (text, terms) =>
  terms.filter((term) => text.includes(term));

return items.map((item) => {
  const j = item.json;

  const title = normalize(j.nombre_del_procedimiento);
  const description = normalize(
    j.descripci_n_del_procedimiento
  );
  const entity = normalize(j.entidad);

  const text = `${title} ${description}`;

  // Familias de productos y servicios.
  const rules = {
    biomedical: [
      "EQUIPO BIOMEDICO",
      "EQUIPOS BIOMEDICOS",
      "BIOMEDIC",
      "DISPOSITIVO MEDICO",
      "EQUIPO MEDICO",
      "EQUIPOS MEDICOS",
      "FOTOTERAPIA",
      "DESFIBRILADOR",
      "ECOGRAFO",
      "ELECTROCARDIOGRAF",
      "VENTILADOR MECANICO",
      "MONITOR DE SIGNOS",
      "MONITOR DE PACIENTE",
      "RAYOS X",
      "TERMOHIGROMETRO"
    ],

    supplies: [
      "MATERIAL MEDICO",
      "MEDICO QUIRURG",
      "INSUMOS MEDICOS",
      "INSUMOS HOSPITALARIOS",
      "DISPOSITIVOS MEDICOS",
      "CATETER",
      "SONDA",
      "SUTURA",
      "CANULA",
      "JERINGA",
      "APOSITO",
      "GUANTES QUIRURGICOS",
      "ASAS LEEP",
      "HEMOCOMPONENT",
      "OXIGENO MEDICINAL",
      "CILINDRO MEDICINAL"
    ],

    laboratory: [
      "REACTIV",
      "EQUIPO DE LABORATORIO",
      "EQUIPOS DE LABORATORIO",
      "LABORATORIO CLINICO",
      "ANALIZADOR",
      "CENTRIFUG",
      "MICROSCOP"
    ],

    furniture: [
      "CAMILLA",
      "CAMA HOSPITALARIA",
      "MOBILIARIO HOSPITAL",
      "MESA QUIRURG",
      "CUNA TERMICA"
    ],

    medicines: [
      "MEDICAMENTO",
      "FARMACO",
      "VACUNA"
    ],

    dental: [
      "EQUIPO ODONTOLOG",
      "MATERIAL ODONTOLOG",
      "UNIDAD ODONTOLOG",
      "CAVITRON"
    ],

    maintenance: [
      "MANTENIMIENTO",
      "CALIBRACION",
      "REPARACION",
      "REPUESTO",
      "SERVICIO TECNICO"
    ],

    digitalHealth: [
      "SOFTWARE",
      "SISTEMA DE INFORMACION",
      "HISTORIA CLINICA ELECTRONICA"
    ],

    personnel: [
      "PRESTACION DE SERVICIOS",
      "SERVICIOS PROFESIONALES",
      "MEDICO GENERAL",
      "MEDICO DE",
      "ENFERMER",
      "AUXILIAR",
      "PSICOLOG",
      "ODONTOLOGO",
      "APOYO A LA GESTION",
      "COORDINADOR",
      "PRESTAR SUS SERVICIOS",
      "PRESTAR SERVICIOS",
      "FACTURACION"
    ]
  };

  const detected = {};

  for (const [key, terms] of Object.entries(rules)) {
    detected[key] = findMatches(text, terms);
  }

  // Identificar intención comercial.
  const purchaseTerms = [
    "COMPRA",
    "ADQUISICION",
    "SUMINISTRO",
    "COMPRAVENTA",
    "ENTREGAR",
    "DOTACION",
    "ORDEN DE COMPRA",
    "ALQUILER",
    "ARRENDAMIENTO"
  ];

  const hasPurchaseIntent = hasAny(text, purchaseTerms);

  // Clasificación del proceso.
  let category = "Revisión manual";
  let commercialType = "No identificado";

  const hasMaintenance =
    detected.maintenance.length > 0;

  const hasMedicalEquipment =
    detected.biomedical.length > 0 ||
    detected.supplies.length > 0 ||
    detected.laboratory.length > 0 ||
    detected.dental.length > 0;

  const isMaintenance =
    hasMaintenance && hasMedicalEquipment;

  if (isMaintenance) {
    category = "Mantenimiento biomédico / técnico";
    commercialType = "Servicio técnico";

  } else if (detected.biomedical.length > 0) {
    category = "Equipos biomédicos";
    commercialType = "Producto";

  } else if (detected.supplies.length > 0) {
    category = "Insumos y dispositivos médicos";
    commercialType = "Producto";

  } else if (detected.dental.length > 0) {
    category = "Equipamiento odontológico";
    commercialType = "Producto";

  } else if (detected.laboratory.length > 0) {
    category = "Laboratorio y diagnóstico";
    commercialType = "Producto / laboratorio";

  } else if (detected.medicines.length > 0) {
    category = "Medicamentos";
    commercialType = "Producto";

  } else if (detected.furniture.length > 0) {
    category = "Mobiliario hospitalario";
    commercialType = "Producto";

  } else if (detected.digitalHealth.length > 0) {
    category = "Software y sistemas de salud";
    commercialType = "Tecnología";

  } else if (detected.personnel.length > 0) {
    category = "Servicios profesionales / talento humano";
    commercialType = "Servicios profesionales";

  } else if (
    /HOSPITAL|SALUD|ESE|IPS|CLINIC/.test(
      `${entity} ${text}`
    )
  ) {
    category = "Otros servicios del sector salud";
    commercialType = "Otros servicios";
  }

  // Normalización del presupuesto.
  const price = Number(
    String(j.precio_base ?? "").replace(/[^\d.-]/g, "")
  ) || 0;

  // Estado de contratación.
  const status = normalize(j.estado_del_procedimiento);
  const adjudicado = normalize(j.adjudicado);
  const statusSummary = normalize(j.estado_resumen);

  let trackingStatus = "POR_VERIFICAR";

  if (status.includes("CANCEL")) {
    trackingStatus = "CANCELADO";
  } else if (
    adjudicado === "SI" ||
    statusSummary.includes("ADJUDICADO")
  ) {
    trackingStatus = "ADJUDICADO";
  } else if (status.includes("BORRADOR")) {
    trackingStatus = "BORRADOR";
  } else if (
    [
      "PUBLICADO",
      "SELECCIONADO",
      "EVALUACION",
      "EN APROBACION",
      "APROBADO"
    ].some((value) => status.includes(value))
  ) {
    trackingStatus = "EN_SEGUIMIENTO";
  }

  // Cálculo determinístico de relevancia.
  const isProduct = [
    "Equipos biomédicos",
    "Insumos y dispositivos médicos",
    "Equipamiento odontológico",
    "Laboratorio y diagnóstico",
    "Medicamentos",
    "Mobiliario hospitalario"
  ].includes(category);

  const isDigital =
    category === "Software y sistemas de salud";

  const isHealthTech =
    isProduct || isMaintenance || isDigital;

  const isHealthEntity =
    /HOSPITAL|SALUD|ESE|IPS|DISPENSARIO|SUBRED/.test(entity);

  let score = 0;

  if (isProduct) score += 55;
  if (isMaintenance) score += 50;
  if (isDigital) score += 45;
  if (hasPurchaseIntent) score += 20;
  if (isHealthEntity) score += 10;
  if (trackingStatus === "EN_SEGUIMIENTO") score += 10;
  if (trackingStatus === "BORRADOR") score -= 5;
  if (
    trackingStatus === "CANCELADO" ||
    trackingStatus === "ADJUDICADO"
  ) score -= 30;
  if (price > 0) score += 5;

  score = Math.max(0, Math.min(100, score));

  const relevance =
    score >= 75 ? "ALTA" :
    score >= 50 ? "MEDIA" : "BAJA";

  // Recomendación de seguimiento.
  let followUp = "Validar manualmente";

  if (trackingStatus === "CANCELADO") {
    followUp = "No monitorear como oportunidad activa";
  } else if (trackingStatus === "ADJUDICADO") {
    followUp = "Conservar como histórico";
  } else if (trackingStatus === "BORRADOR") {
    followUp = "Vigilar posible publicación";
  } else if (trackingStatus === "EN_SEGUIMIENTO") {
    followUp = "Revisar disponibilidad en SECOP";
  }

  // Conservamos los campos originales y agregamos
  // nuestros campos analíticos.
  return {
    json: {
      ...j,

      healthtech_categoria: category,
      healthtech_tipo_comercial: commercialType,
      healthtech_score: score,
      healthtech_relevancia: relevance,

      healthtech_es_relevante: isHealthTech,
      healthtech_es_compra:
        isProduct && hasPurchaseIntent,
      healthtech_intencion_compra: hasPurchaseIntent,

      healthtech_estado: trackingStatus,
      healthtech_seguimiento: followUp,

      healthtech_evidencia: Object.entries(detected)
        .filter(([, matches]) => matches.length > 0)
        .map(([key, matches]) => `${key}: ${matches.join(", ")}`),

      precio_base_numero: price,
      url_secop: j.urlproceso?.url ?? null,

      fecha_publicacion:
        j.fecha_de_publicacion_del ?? null,

      fecha_ultima_publicacion:
        j.fecha_de_ultima_publicaci ?? null
    }
  };
});

// ============================================================
// HEALTHTECH OPPORTUNITY QUALIFICATION v2.0
// Clasificación comercial + validación de oportunidades SECOP
// ============================================================

// Normalizar textos: mayúsculas, sin tildes y sin espacios extremos
const normalize = (value) =>
  String(value ?? "")
    .trim()
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

// Interpretar valores booleanos provenientes de SECOP
const toBool = (value) => {
  if (typeof value === "boolean") return value;

  return ["TRUE", "1", "SI", "YES"].includes(
    normalize(value)
  );
};

// Obtener el primer valor disponible
const firstValue = (...values) =>
  values.find(
    value =>
      value !== null &&
      value !== undefined &&
      String(value).trim() !== ""
  ) ?? null;

// Obtener fecha actual de Colombia
const getTodayBogota = () => {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Bogota",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(new Date());

  const get = type =>
    parts.find(part => part.type === type)?.value;

  return `${get("year")}-${get("month")}-${get("day")}`;
};

// Convertir una fecha a YYYY-MM-DD sin desplazar
// el día por diferencias de zona horaria
const parseDate = (value) => {
  if (!value) return null;

  const text = String(value).trim();

  const match = text.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (match) {
    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);

    const date = new Date(Date.UTC(year, month - 1, day));

    if (
      date.getUTCFullYear() !== year ||
      date.getUTCMonth() !== month - 1 ||
      date.getUTCDate() !== day
    ) {
      return null;
    }

    return text.slice(0, 10);
  }

  const date = new Date(text);

  if (Number.isNaN(date.getTime())) return null;

  return [
    date.getUTCFullYear(),
    String(date.getUTCMonth() + 1).padStart(2, "0"),
    String(date.getUTCDate()).padStart(2, "0")
  ].join("-");
};

// Diferencia en días calendario
const daysBetween = (from, to) => {
  if (!from || !to) return null;

  const timestamp = date =>
    Date.UTC(
      Number(date.slice(0, 4)),
      Number(date.slice(5, 7)) - 1,
      Number(date.slice(8, 10))
    );

  return Math.round(
    (timestamp(to) - timestamp(from)) / 86400000
  );
};

const today = getTodayBogota();

// ============================================================
// PROCESAMIENTO DE REGISTROS
// ============================================================

return $input.all().map(({ json: p }) => {

  // ----------------------------------------------------------
  // 1. DATOS DE CLASIFICACIÓN EXISTENTES
  // ----------------------------------------------------------

  const score = Number(p.healthtech_score) || 0;

  const tipoComercial = normalize(
    p.healthtech_tipo_comercial
  );

  const esCompraProducto =
    toBool(p.healthtech_es_compra) &&
    toBool(p.healthtech_intencion_compra) &&
    tipoComercial === "PRODUCTO";

  const estado = normalize(
    p.estado_del_procedimiento
  );

  const estadoResumen = normalize(
    p.estado_resumen
  );

  const estadoCompleto = `${estado} ${estadoResumen}`;

  const adjudicado =
    toBool(p.adjudicado) ||
    estadoCompleto.includes("ADJUDICADO");

  const cancelado =
    estadoCompleto.includes("CANCELADO");

  const esPublicado =
    estadoCompleto.includes("PUBLICADO");

  const esBorrador =
    estadoCompleto.includes("BORRADOR") ||
    estadoCompleto.includes("APROBADO") ||
    estadoCompleto.includes("EN APROBACION");

  const esEvaluacion =
    estadoCompleto.includes("EVALUACION");

  const esSeleccionado =
    estadoCompleto.includes("SELECCIONADO");

  const fase = normalize(
    `${p.fase || ""} ${p.estado_resumen || ""}`
  );

  const faseOferta = fase.includes("OFERTA");

  // ----------------------------------------------------------
  // 2. VALIDACIÓN DE ENLACES SECOP
  // ----------------------------------------------------------

  const url = String(
    p.url_secop ||
    p.urlproceso?.url ||
    ""
  );

  const enlaceDirecto =
    /noticeUID=CO1\.NTC\./i.test(url);

  // ----------------------------------------------------------
  // 3. VALIDACIÓN DE FECHAS
  // ----------------------------------------------------------

  // Fecha estimada de cierre o recepción de ofertas
  const fechaLimiteOriginal = firstValue(
    p.fecha_de_recepcion_de,
    p.fecha_limite_ofertas,
    p.fecha_limite,
    p.fecha_de_cierre,
    p.fecha_cierre
  );

  const fechaLimite = parseDate(fechaLimiteOriginal);

  const diasParaCierre = fechaLimite
    ? daysBetween(today, fechaLimite)
    : null;

  // Fecha de apertura efectiva
  const fechaApertura = parseDate(
    firstValue(
      p.fecha_de_apertura_efectiva,
      p.fecha_apertura
    )
  );

  // Fecha de adjudicación
  const fechaAdjudicacion = parseDate(
    p.fecha_adjudicacion
  );

  // Fecha de publicación para medir antigüedad
  const fechaReferencia = parseDate(
    firstValue(
      p.fecha_ultima_publicacion,
      p.fecha_publicacion,
      p.fecha_de_apertura_efectiva
    )
  );

  const antiguedadDias = fechaReferencia
    ? daysBetween(fechaReferencia, today)
    : null;

  // Consideramos antiguo un proceso con más de 90 días.
  // Si no hay fecha, también requiere revisión manual.
  const revisarAntiguedad =
    esBorrador &&
    (
      antiguedadDias === null ||
      antiguedadDias > 90
    );

  const antiguedadEstado =
    antiguedadDias === null
      ? "SIN_FECHA_REFERENCIA"
      : antiguedadDias > 90
        ? "ANTIGUO"
        : antiguedadDias < 0
          ? "FECHA_FUTURA"
          : "RECIENTE";

  // ----------------------------------------------------------
  // 4. ESTADO COMERCIAL DEL RADAR
  // ----------------------------------------------------------

  let radarEstado;

  if (cancelado) {
    radarEstado = "CANCELADO";

  } else if (adjudicado) {
    radarEstado = "ADJUDICADO";

  } else if (!esCompraProducto) {
    radarEstado = "NO_PRODUCTO";

  } else if (esBorrador) {
    radarEstado = "BORRADOR_VALIDAR_ANTIGUEDAD";

  } else if (
    esPublicado &&
    faseOferta &&
    fechaLimite &&
    diasParaCierre < 0
  ) {
    radarEstado = "PLAZO_VENCIDO_POR_VALIDAR";

  } else if (
    esPublicado &&
    faseOferta &&
    fechaLimite &&
    diasParaCierre >= 0
  ) {
    radarEstado = "ACTIVA_CON_FECHA_LIMITE";

  } else if (
    esPublicado &&
    faseOferta &&
    !fechaLimite
  ) {
    radarEstado = "ACTIVA_POR_VALIDAR_FECHA";

  } else if (esEvaluacion) {
    radarEstado = "PROCESO_EN_EVALUACION";

  } else if (esSeleccionado) {
    radarEstado = "PROCESO_SELECCIONADO";

  } else if (esPublicado) {
    radarEstado = "PUBLICADO_VALIDAR_FASE";

  } else {
    radarEstado = "REVISION_MANUAL";
  }

  // ----------------------------------------------------------
  // 5. RELEVANCIA COMERCIAL
  // ----------------------------------------------------------

  let relevanciaComercial;

  if (score >= 80) {
    relevanciaComercial = "ALTA";
  } else if (score >= 50) {
    relevanciaComercial = "MEDIA";
  } else {
    relevanciaComercial = "BAJA";
  }

  // ----------------------------------------------------------
  // 6. PRIORIDAD DE ACCIÓN
  // Separa interés comercial de urgencia operativa.
  // ----------------------------------------------------------

  let prioridadAccion;

  if (
    !esCompraProducto ||
    cancelado ||
    adjudicado
  ) {
    prioridadAccion = "NO_APLICA";

  } else if (
    radarEstado === "ACTIVA_CON_FECHA_LIMITE"
  ) {
    if (
      diasParaCierre <= 7 ||
      score >= 80
    ) {
      prioridadAccion = "ALTA";
    } else if (score >= 50) {
      prioridadAccion = "MEDIA";
    } else {
      prioridadAccion = "BAJA";
    }

  } else if (
    radarEstado === "ACTIVA_POR_VALIDAR_FECHA"
  ) {
    prioridadAccion =
      score >= 80 ? "ALTA" :
      score >= 50 ? "MEDIA" : "BAJA";

  } else if (
    radarEstado === "BORRADOR_VALIDAR_ANTIGUEDAD"
  ) {
    prioridadAccion =
      score >= 80 ? "MEDIA" : "BAJA";

  } else if (
    radarEstado === "PROCESO_EN_EVALUACION" ||
    radarEstado === "PROCESO_SELECCIONADO"
  ) {
    prioridadAccion =
      score >= 80 ? "MEDIA" : "BAJA";

  } else {
    prioridadAccion = "BAJA";
  }

  // ----------------------------------------------------------
  // 7. ACCIÓN RECOMENDADA
  // ----------------------------------------------------------

  let accionRecomendada;

  switch (radarEstado) {

    case "ACTIVA_CON_FECHA_LIMITE":
      accionRecomendada =
        "Validar requisitos y preparar oferta";
      break;

    case "ACTIVA_POR_VALIDAR_FECHA":
      accionRecomendada =
        "Consultar fecha límite y disponibilidad en SECOP";
      break;

    case "PLAZO_VENCIDO_POR_VALIDAR":
      accionRecomendada =
        "Verificar cierre, modificaciones o ampliaciones en SECOP";
      break;

    case "BORRADOR_VALIDAR_ANTIGUEDAD":
      accionRecomendada =
        "Verificar antigüedad y posible publicación";
      break;

    case "PROCESO_EN_EVALUACION":
      accionRecomendada =
        "Consultar evaluación y posibles resultados";
      break;

    case "PROCESO_SELECCIONADO":
      accionRecomendada =
        "Verificar adjudicación del proceso";
      break;

    case "PUBLICADO_VALIDAR_FASE":
      accionRecomendada =
        "Verificar fase contractual en SECOP";
      break;

    case "ADJUDICADO":
      accionRecomendada =
        "Conservar como histórico";
      break;

    case "CANCELADO":
      accionRecomendada =
        "No monitorear como oportunidad activa";
      break;

    case "NO_PRODUCTO":
      accionRecomendada =
        "Excluir de oportunidades de compra de productos";
      break;

    default:
      accionRecomendada =
        "Revisión manual del proceso";
  }

  // ----------------------------------------------------------
  // 8. SALIDA ENRIQUECIDA
  // Conserva todos los campos anteriores.
  // ----------------------------------------------------------

  return {
    json: {
      ...p,

      // Clasificación comercial
      radar_es_compra_producto: esCompraProducto,
      radar_relevancia_comercial: relevanciaComercial,
      radar_prioridad: relevanciaComercial,
      radar_prioridad_accion: prioridadAccion,

      // Estado del proceso
      radar_estado: radarEstado,
      radar_fase_oferta: faseOferta,

      // Enlaces
      radar_enlace_directo: enlaceDirecto,
      radar_revisar_enlace:
        esCompraProducto && !enlaceDirecto,

      // Fechas
      radar_fecha_limite: fechaLimite,
      radar_fuente_fecha_limite:
        fechaLimite ? "fecha_de_recepcion_de" : null,

      radar_dias_para_cierre: diasParaCierre,

      radar_fecha_apertura: fechaApertura,
      radar_fecha_adjudicacion: fechaAdjudicacion,

      radar_fecha_referencia_antiguedad:
        fechaReferencia,

      // Antigüedad
      radar_antiguedad_dias: antiguedadDias,
      radar_antiguedad_estado: antiguedadEstado,
      radar_revisar_antiguedad: revisarAntiguedad,

      // Validaciones pendientes
      radar_validar_fecha:
        esCompraProducto && !fechaLimite,

      radar_validar_estado:
        esCompraProducto &&
        radarEstado === "REVISION_MANUAL",

      // Acción sugerida
      radar_accion_recomendada: accionRecomendada,

      // Fecha de ejecución
      radar_fecha_evaluacion: today
    }
  };
});

const records = $input.all();

// Limpieza de textos procedentes de SECOP
const limpiarTexto = (valor) =>
  String(valor ?? '')
    .replace(/\*/g, '')
    .replace(/<[^>]*>/g, '')
    .trim();
const now = new Date();

const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/Bogota',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(now).map(p => [p.type, p.value])
);

const fechaAlerta =
  `${parts.year}-${parts.month}-${parts.day} ` +
  `${parts.hour}:${parts.minute}:${parts.second}`;

const candidates = new Map();

for (const { json: p } of records) {
  const estado = String(p.radar_estado ?? '').toUpperCase();
  const prioridad = String(
    p.radar_prioridad_accion ?? ''
  ).toUpperCase();

  // Solo oportunidades publicadas y de prioridad alta
  if (
    estado !== 'ACTIVA_POR_VALIDAR_FECHA' ||
    prioridad !== 'ALTA' ||
    !p.id_del_proceso ||
    p.radar_enlace_directo !== true
  ) {
    continue;
  }

  const id = String(p.id_del_proceso);
  const fechaLimite = String(p.radar_fecha_limite ?? '');

  // Un cambio de estado, prioridad o fecha genera
  // una alerta nueva para el mismo proceso.
  const alertKey = [
    id,
    estado,
    prioridad,
    fechaLimite || 'SIN_FECHA'
  ].join('|');

  const precio = Number(p.precio_base_numero) || 0;

  const precioTexto = precio > 0
    ? `$${precio.toLocaleString('es-CO')} COP`
    : 'No informado';

  const mensaje = [
    '🚨 NUEVA OPORTUNIDAD HEALTH TECH',
    '',
    `📌 Proceso: ${p.referencia_del_proceso || id}`,
    `🏥 Entidad: ${limpiarTexto(p.entidad) || 'No informada'}`,
    `📍 Ubicación: ${p.ciudad_entidad || 'No definida'}, ${p.departamento_entidad || 'No definido'}`,
    '',
    `🩺 Categoría: ${p.healthtech_categoria || 'No definida'}`,
    `📦 Objeto: ${p.descripcion || p.nombre_del_procedimiento || 'No informado'}`,
    `💰 Presupuesto: ${precioTexto}`,
    '',
    `⚡ Prioridad: ${prioridad}`,
    `📊 Estado radar: ${estado}`,
    `📅 Fecha límite: ${fechaLimite || 'No identificada; verificar en SECOP'}`,
    '',
    '🔗 Consultar proceso:',
    p.url_secop || 'Enlace no disponible',
    '',
    'Sistema: HealthTech Procurement Radar'
  ].join('\n');

  if (!candidates.has(alertKey)) {
    candidates.set(alertKey, {
      json: {
        alert_key: alertKey,
        id_del_proceso: id,
        radar_estado: estado,
        radar_prioridad_accion: prioridad,
        radar_fecha_limite: fechaLimite,
        fecha_alerta: fechaAlerta,
        mensaje_telegram: mensaje
      }
    });
  }
}

return Array.from(candidates.values());
